SELECT CASE WHEN s.rating >= 4.1 THEN 'high' WHEN s.rating >= 2.1 THEN 'mid' ELSE 'low' END AS rating_bucket, ROUND(STDDEV(oi.quantity), 2) AS stddev_quantity, MAX(oi.unit_price) AS max_unit_price FROM order_items oi FULL OUTER JOIN products p ON oi.product_id = p.id LEFT OUTER JOIN suppliers s ON s.id = p.supplier_id GROUP BY CASE WHEN s.rating >= 4.1 THEN 'high' WHEN s.rating >= 2.1 THEN 'mid' ELSE 'low' END ORDER BY rating_bucket;
